ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_data *data = file->private_data;
    ssize_t total_bytes_read = 0;
    int ret;

    if (!data)
        return -EINVAL;

    spin_lock(&data->lock);

    while (total_bytes_read < count) {
        if (kthread_should_stop())
            break;

        if (data->disconnected) {
            ret = -ENODEV;
            break;
        }

        if (data->queue_empty) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                break;
            }

            spin_unlock(&data->lock);

            ret = wait_event_interruptible(data->read_wait, !data->queue_empty);
            if (ret)
                return ret;

            spin_lock(&data->lock);
            continue;
        }

        size_t bytes_available = data->queue_size;
        size_t bytes_to_read = min(count - total_bytes_read, bytes_available);

        ret = copy_to_user(buffer + total_bytes_read, data->queue, bytes_to_read);
        if (ret) {
            ret = -EFAULT;
            break;
        }

        total_bytes_read += bytes_to_read;
        data->queue += bytes_to_read;
        data->queue_size -= bytes_to_read;

        if (data->queue_size == 0)
            data->queue_empty = true;

        spin_unlock(&data->lock);

        wake_up(&data->write_wait);

        spin_lock(&data->lock);
    }

    spin_unlock(&data->lock);

    return total_bytes_read ? total_bytes_read : ret;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_data *data = file->private_data;
    ssize_t total_bytes_read = 0;
    size_t bytes_read;
    int ret;

    if (!data)
        return -EINVAL;

    mutex_lock(&data->mutex);
    spin_lock_irq(&data->spinlock);

    while (total_bytes_read < count) {
        if (kthread_should_stop()) {
            ret = -ENODEV;
            goto unlock;
        }

        if (data->disconnected) {
            ret = -EIO;
            goto unlock;
        }

        if (data->queue_empty) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                goto unlock;
            }
            wait_event_interruptible(data->read_wait_queue, !data->queue_empty);
        }

        bytes_read = copy_to_user(buffer + total_bytes_read, data->buffer, count - total_bytes_read);
        if (bytes_read != 0) {
            ret = -EFAULT;
            goto unlock;
        }

        total_bytes_read += count - bytes_read;
        data->queue_empty = is_queue_empty(data->queue);
    }

    unlock:
    spin_unlock_irq(&data->spinlock);
    mutex_unlock(&data->mutex);

    return (ret < 0) ? ret : total_bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_private *priv = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!priv)
        return -EINVAL;

    spin_lock(&priv->spinlock);
    mutex_lock(&priv->mutex);

    while (count > 0) {
        if (kthread_should_stop()) {
            ret = -ENODEV;
            break;
        }

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            break;
        }

        if (priv->disconnected) {
            ret = -EIO;
            break;
        }

        if (priv->queue_size == 0) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                break;
            } else {
                mutex_unlock(&priv->mutex);
                wait_event_interruptible(priv->read_wait, (priv->queue_size > 0 || kthread_should_stop()));
                mutex_lock(&priv->mutex);
                continue;
            }
        }

        ret = copy_to_user(buffer + bytes_read, priv->queue, min(count, priv->queue_size));
        if (ret) {
            ret = -EFAULT;
            break;
        }

        bytes_read += min(count, priv->queue_size);
        count -= min(count, priv->queue_size);
        priv->queue_size -= min(count + bytes_read, priv->queue_size);
        priv->read_index = (priv->read_index + min(count + bytes_read, priv->queue_size)) % priv->buffer_size;
    }

    mutex_unlock(&priv->mutex);
    spin_unlock(&priv->spinlock);

    if (ret < 0)
        return ret;

    return bytes_read;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_data *data = file->private_data;
    ssize_t total_bytes_read = 0;
    int bytes_to_read;

    if (!data)
        return -EINVAL;

    mutex_lock(&data->mutex);
    spin_lock(&data->spinlock);

    while (total_bytes_read < count && !kthread_should_stop()) {
        if (data->disconnected) {
            spin_unlock(&data->spinlock);
            mutex_unlock(&data->mutex);
            return -ENODEV;
        }

        if (data->queue_size == 0) {
            if (file->f_flags & O_NONBLOCK) {
                spin_unlock(&data->spinlock);
                mutex_unlock(&data->mutex);
                return -EAGAIN;
            } else {
                wait_for_data(data);
            }
            continue;
        }

        bytes_to_read = min(count - total_bytes_read, (size_t)data->queue_size);
        if (copy_to_user(buffer + total_bytes_read, data->queue, bytes_to_read)) {
            spin_unlock(&data->spinlock);
            mutex_unlock(&data->mutex);
            return -EFAULT;
        }

        total_bytes_read += bytes_to_read;
        advance_queue(data, bytes_to_read);
    }

    spin_unlock(&data->spinlock);
    mutex_unlock(&data->mutex);

    return total_bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    void *private_data = file->private_data;
    ssize_t total_bytes_read = 0;
    int ret;

    if (!private_data)
        return -EFAULT;

    while (total_bytes_read < (ssize_t)count) {
        struct mutex *lock = get_mutex(private_data);
        struct spinlock *spinlock = get_spinlock(private_data);
        char data[BUFSIZ];
        size_t bytes_to_read;

        if (check_disconnection(private_data))
            return -ENODEV;

        if (signal_pending(current))
            return -ERESTARTSYS;

        mutex_lock(lock);
        spin_lock(spinlock);

        bytes_to_read = min(count - total_bytes_read, (size_t)sizeof(data));
        ret = read_from_timer_queue(private_data, data, bytes_to_read);

        spin_unlock(spinlock);
        mutex_unlock(lock);

        if (ret <= 0) {
            if (ret == 0)
                break;
            if (ret != -EAGAIN || (file->f_flags & O_NONBLOCK))
                return ret;
            ret = wait_for_readable(private_data);
            if (ret < 0)
                return ret;
            continue;
        }

        if (copy_to_user(buffer + total_bytes_read, data, ret)) {
            return -EFAULT;
        }

        total_bytes_read += ret;
    }

    return total_bytes_read;
}
